#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/fnox/tasks/setup-secrets-fnox.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Check that every secret of each fnox profile is configured"
# MISE hide=true
# MISE tools={uv="latest", python="3.14"}

import os
import re
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402

MIN_VERSION = "1.39.0"


def _number(part):
  """The number at the start of part, as `part + 0` of awk; 0 when it has none."""
  match = re.match(r"\s*([+-]?\d+)", part)
  return int(match.group(1)) if match else 0


def at_least(version, minimum):
  """Whether the dotted version is minimum or newer, compared on the first
  three parts."""
  a = version.split(".")
  b = minimum.split(".")
  for i in range(3):
    x = _number(a[i]) if i < len(a) else 0
    y = _number(b[i]) if i < len(b) else 0
    if x > y:
      return True
    if x < y:
      return False
  return True


def output(*args):
  """The stdout of `mise x -- <args>` without the newlines at the end, or ''
  when the command fails. stderr is discarded."""
  result = helpers.tool(*args, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, text=True)
  return result.stdout.rstrip("\n") if result.returncode == 0 else ""


def main():
  root = os.environ["MISE_PROJECT_ROOT"]
  # A repository without a fnox config has no secrets to check.
  if not os.path.isfile(f"{root}/.config/fnox.toml"):
    return 0

  helpers.print_header("Checking secrets with fnox ...")

  if not helpers.has_tool("fnox"):
    helpers.print_warn("fnox is not on PATH — skipping secrets setup.")
    helpers.print_yellow("Install the repo's pinned tools with 'mise install', then re-run this task.")
    return 0

  # fnox finds .config/fnox.toml from the repository root. `--config` is not
  # used: it also stops the search, but it still loads the global config.
  os.chdir(root)

  # fnox 1.36.0 does not search .config/, and 1.39.0 does. With an older
  # version, fnox finds no config here.
  version = output("fnox", "--version").rpartition(" ")[2]
  if not at_least(version, MIN_VERSION):
    helpers.print_warn(f"fnox {version or '<unknown>'} is older than {MIN_VERSION} — skipping secrets setup.")
    helpers.print_yellow("Run 'mise upgrade fnox', then re-run this task.")
    return 0

  # A repository does not use the fnox `default` profile: its secrets live in
  # `[profiles.<name>]` tables, and the sync stops on a top-level `[secrets]`
  # table. Thus each named profile gets its own `fnox -P <name> check`, and
  # `default` gets none. `fnox -P a,b check` merges the profiles into one
  # overlay, where a later profile replaces a secret of the same name, so a
  # missing secret of an earlier profile can stay hidden. `fnox profiles`
  # always lists `default`; its profile lines are indented, and the first word
  # of each is the name.
  names = []
  for line in output("fnox", "profiles").split("\n"):
    if not re.match(r"[ \t\n\r\f\v]", line):
      continue
    name = re.split(r"[ \t]+", line.strip(" \t"))[0]
    if name and name != "default":
      names.append(name)

  if not names:
    helpers.print_error(".config/fnox.toml has no named profile.")
    helpers.print_yellow("Move the secrets to [profiles.<repo_name>.secrets] (M25 of docs/sync/migrate.md).")
    return 1

  # Every check runs, also after one fails, so one run shows each profile that
  # needs a secret.
  failed = []
  for name in names:
    helpers.print_subheader(f"Checking the profile {name} ...")
    if helpers.tool("fnox", "-P", name, "check").returncode != 0:
      failed.append(name)

  if failed:
    helpers.print_error(f"fnox check failed for the profile(s): {' '.join(failed)}")
    return 1
  return 0


if __name__ == "__main__":
  sys.exit(main())
